-- Wylogowanie wszystkich sesji profilu admina, raz (0.35.0): sesja mogła zostać na cudzym komputerze. Launcher właściciela
-- zaloguje się od nowa sam, kontem Minecraft.
do $$ begin
  if not exists (select 1 from private.migrations where id = 'sesje-admina-0.35') then
    if to_regclass('auth.refresh_tokens') is not null then
      execute 'delete from auth.refresh_tokens where user_id in (select user_id::text from private.admins)';
    end if;
    delete from auth.sessions where user_id in (select user_id from private.admins);
    delete from private.admin_unlocks;
    insert into private.migrations (id) values ('sesje-admina-0.35');
  end if;
exception when insufficient_privilege then
  raise notice 'Nie udało się wylogować sesji admina: zrób to ręcznie (supabase/README.md).';
end $$;

-- panel admina: wywołać może każdy zalogowany, ale każda funkcja sama sprawdza, czy to admin
revoke all on function private.need_admin() from public, anon, authenticated;
revoke all on function private.random_code() from public, anon, authenticated;
revoke all on function public.is_admin() from public, anon, authenticated;
grant execute on function public.is_admin() to authenticated;
revoke all on function public.admin_status() from public, anon, authenticated;
grant execute on function public.admin_status() to authenticated;
revoke all on function public.admin_unlock(text, text) from public, anon, authenticated;
grant execute on function public.admin_unlock(text, text) to authenticated;
revoke all on function private.session_id() from public, anon, authenticated;
do $$
declare f text;
begin
  for f in select p.oid::regprocedure::text from pg_proc p join pg_namespace n on n.oid = p.pronamespace
           where n.nspname = 'public' and p.proname like 'admin\_%' loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to authenticated', f);
  end loop;
end $$;
